insert into lsicorp.doc_pages (product_slug, slug, title, summary, audience, sort_order, body, last_reviewed, status)
values ('podcast-radio', 'getting-started', 'Getting started with LSI Podcast and Online Radio', 'The intended journeys for listeners and creators.', 'Listeners and creators', 1, 'LSI Podcast and Online Radio is a product concept. Nothing has been released, so this page describes what is intended.

## For listeners

1. Find a show, episode or radio channel.
2. Play it, and use the listening controls to pause or move through it.
3. Follow shows you like.

## For creators

1. Set up a show or a radio channel and add its details.
