insert into lsicorp.pages (slug, title, description, body, last_reviewed)
values ('about', 'About LSI Corp', 'Technology, logistics and finance connected around real-world commerce.', 'Founded in 2016, Lifestyle Investment Corp (LSI) works across technology, logistics and finance. LSI designs smart, scalable solutions that connect digital platforms, efficient logistics networks and secure financial systems.

## Our mission

To simplify and enable commerce. By connecting innovation with practical execution, LSI helps businesses move goods, transact with confidence and build for sustainable growth in an increasingly digital economy.

## How LSI creates value

**Connected design.** LSI brings digital services, operational workflows and financial tools together, so that each part supports the wider customer and business journey.

**Practical execution.** Products are shaped around everyday needs: finding and selling goods, arranging delivery, accessing media and understanding markets.

**Scalable foundations.** LSI focuses on systems that can grow across users, merchants, partners and new service areas over time.

## At a glance

- **Founded:** 2016
- **Core focus:** technology, logistics and finance
- **Approach:** integrated platforms and real-world delivery
- **Purpose:** make commerce simpler, more connected and easier to scale

## Our work

LSI''s portfolio applies technology to distinct needs: connected commerce, media playback, spoken-audio publishing and listening, and market research. The projects are at different stages of definition and development, and each is shown with its true status.

See [what we do](/services), browse [our work](/work) or [get in touch](/contact).
', '2026-10-06')
on conflict (slug) do nothing;

insert into lsicorp.pages (slug, title, description, body, last_reviewed)
values ('accessibility', 'Accessibility statement', 'How this website supports accessibility and how to report a problem.', 'LSI Corp wants this website to be usable by as many people as possible. Our target is the Web Content Accessibility Guidelines (WCAG) 2.2, level AA.

## What we have done

- Every control can be reached and used with a keyboard, with a visible focus indicator.
- Status is always written in words and never shown by colour alone.
- Text and controls are designed to meet AA contrast in light and dark colour schemes.
- The site does not play audio or video automatically and does not rely on animation.
- Download buttons name their platform and version.

## Known limitations

This website is an application drawn inside the browser rather than a set of standard web pages. Because of that:

- Screen reader support depends on your browser and may be incomplete.
- Browser features such as find-in-page, text zoom and reader mode may not work as they do on ordinary pages.
- The first visit needs a larger download than a typical web page.

A short plain-text summary of the site is shown if the application cannot start.

## Reporting a problem

If something on this site is not accessible to you, please tell us through [the contact page](/contact).
', '2026-10-06')
on conflict (slug) do nothing;

insert into lsicorp.pages (slug, title, description, body, last_reviewed)
values ('privacy', 'Privacy notice', 'What this website collects and how it is used.', 'This notice covers the LSI Corp website only. Each product in our portfolio has its own privacy information, linked from its page once the product is released.

## What this website collects

- **Browsing the site.** You do not need an account. The website does not use advertising or cross-site tracking, and sets no cookies for visitors.
- **The contact form.** If you send us an enquiry, we receive what you enter: your name, your email address, your organisation if you give one, the service you are asking about and your message. We use it only to reply to you and to handle your enquiry. You are asked to agree to this before sending.
- **Staff sign-in.** If you are a member of LSI staff and sign in, your sign-in session is stored in your browser so that you stay signed in.
- **Technical logs.** The services that host this website and its content may keep standard technical logs, such as IP address and time of request, to keep the service secure and working.

Do not put passwords, payment details or other sensitive information in the contact form.

## Who can see an enquiry

Only LSI staff. Enquiries are not published and are not shared with other organisations.

## Asking us to remove your details

Tell us through the [contact page](/contact) and we will delete your enquiry.

## Links to other sites

Download and launch buttons can take you to an app store or to a product''s own domain. Those links are labelled, and the destination''s own privacy terms apply once you leave.

## Changes

If this notice changes, the review date shown on this page is updated.
', '2026-10-06')
on conflict (slug) do nothing;

insert into lsicorp.pages (slug, title, description, body, last_reviewed)
values ('terms', 'Terms of use', 'The terms for using this website.', 'These terms cover the LSI Corp website. Each product has its own terms and licence, shown with its releases.

## Information on this site

LSI aims to keep product status, documentation and release details accurate. Products marked In Development or Coming Soon are not available, and planned features may change or may not be released.

## Downloads

Only use downloads and links published on this website. Check the version, platform and compatibility details before installing. For direct file downloads, compare the published SHA-256 checksum with the file you received.

## Market analysis

Where a product provides market research or analysis, that analysis is not financial advice and does not guarantee returns.
', '2026-10-06')
on conflict (slug) do nothing;

-- FAQs have no natural key, so they are only added to an empty table.
do $$
begin
  if not exists (select 1 from lsicorp.faqs) then
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('1145', 'Can I use 1145 Lifestyle today?', 'Not yet. 1145 Lifestyle is in development and no web app or store listing has been published on this site. When a release is approved, an Open or Download button will appear on the product page.', 'Availability', null, true, 1);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('1145', 'Where will I sign in?', 'On the product''s own domain or in its official app. This website is a catalogue and never asks for your 1145 Lifestyle sign-in or payment details.', 'Accounts', null, true, 2);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('1145', 'Will every module launch together?', 'Not necessarily. Marketplace, merchant, delivery, ride and financial features are tracked separately, and each is marked Available only once it has been released.', 'Availability', null, true, 3);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('1145hz', 'Is 1145Hz Player the same as LSI Player?', 'Yes. 1145Hz Player is the public name of the media player project that earlier LSI material calls LSI Player. They are one product.', 'About', null, true, 1);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('1145hz', 'Where can I download it?', 'There is no download yet. When a release is approved it will be listed on the Downloads page with its version, platform, file size and checksum.', 'Availability', null, true, 2);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('1145hz', 'Will voice control work on my device?', 'That has not been confirmed. Voice features will only be promised on platforms where a release states they are implemented.', 'Voice control', null, true, 3);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('gold-digger', 'Does LSI Gold Digger tell me what to trade?', 'No. It is a research and analysis tool. It does not give financial advice, and its analysis does not guarantee returns.', 'Risk', null, true, 1);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('gold-digger', 'Can it connect to my XM account or place trades?', 'No. XM connectivity and trade execution are not implemented and not approved. They will only be shown as available if that changes.', 'Account connection', null, true, 2);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('gold-digger', 'Where does the market data come from?', 'Data sources, timestamps and refresh intervals will be documented before the first release.', 'Data', null, true, 3);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('podcast-radio', 'Can I publish a podcast or start a radio channel now?', 'No. LSI Podcast and Online Radio is a product concept and nothing has been released.', 'Availability', null, true, 1);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('podcast-radio', 'What file formats will I be able to upload?', 'Accepted formats and file limits have not been decided. They will be specified here before launch.', 'Creators', null, true, 2);
    insert into lsicorp.faqs (product_slug, question, answer, category, escalation, visible, sort_order) values ('podcast-radio', 'Will there be analytics, sharing or offline listening?', 'They are planned, not available. Each will be marked Available only when it has been released.', 'Features', null, true, 3);
  end if;
end
$$;
